mal_0125","concept_label":"0,125 en fraction","type":"mcq","prompt":"0,125 est égal à…","explanation":"1/2 = 0,5 ; 1/4 = 0,25 ; 1/8 = 0,125.","takeaway":"Chaque division par 2 : 0,5 → 0,25 → 0,125.","difficulty":50,"status":"published","payload":{"options":[{"id":"a91c1903","text":"1/8"},{"id":"2173276a","text":"1/6"},{"id":"f3e89572","text":"1/12"},{"id":"88dee1d2","text":"1/4"}]},"answer":{"option_id":"a91c1903"}},{"external_key":"calc-016","concept_id":"calc.conversions.seconds_hour","concept_label":"Secondes dans une heure","type":"numeric","prompt":"Combien y a-t-il de secondes dans une heure ?","explanation":"60 minutes × 60 secondes = 3 600 secondes.","difficulty":30,"status":"published","payload":{"decimals":0,"allow_negative":false},"answer":{"value":3600,"tolerance":0}},{"external_key":"calc-017","concept_id":"calc.conversions.km_to_m","concept_label":"km en m","type":"numeric","prompt":"2,5 km, cela fait combien de mètres ?","explanation":"1 km = 1 000 m, donc 2,5 km = 2 500 m.","difficulty":28,"status":"published","payload":{"decimals":0,"unit":"m","allow_negative":false},"answer":{"value":2500,"tolerance":0}},{"external_key":"calc-018","concept_id":"calc.conversions.litre_cm3","concept_label":"Litre en cm³","type":"numeric","prompt":"Un litre, c''est combien de centimètres cubes ?","explanation":"1 L = 1 dm³ = 10 cm × 10 cm × 10 cm = 1 000 cm³.","takeaway":"1 mL = 1 cm³.","difficulty":50,"status":"published","payload":{"decimals":0,"unit":"cm³","allow_negative":false},"answer":{"value":1000,"tolerance":0}},{"external_key":"calc-019","concept_id":"calc.conversions.hectare","concept_label":"Hectare en m²","type":"numeric","prompt":"Un hectare représente combien de mètres carrés ?","explanation":"Un hectare est un carré de 100 m de côté : 100 × 100 = 10 000 m².","takeaway":"Un terrain de football fait environ 0,7 hectare.","difficulty":55,"status":"published","payload":{"decimals":0,"unit":"m²","allow_negative":false},"answer":{"value":10000,"tolerance":0}},{"external_key":"calc-020","concept_id":"calc.number_logic.seq_pronic","concept_label":"Suite 2, 6, 12, 20…","type":"numeric","prompt":"Quel nombre suit : 2, 6, 12, 20, 30, … ?","explanation":"Les écarts augmentent de 2 : +4, +6, +8, +10, puis +12. 30 + 12 = 42. (C''est aussi n × (n+1).)","difficulty":55,"status":"published","payload":{"decimals":0,"allow_negative":false},"answer":{"value":42,"tolerance":0}},{"external_key":"calc-021","concept_id":"calc.number_logic.prime_after_20","concept_label":"Premier après 20","type":"numeric","prompt":"Quel est le plus petit nombre premier supérieur à 20 ?","explanation":"21 = 3 × 7 et 22 = 2 × 11 ne sont pas premiers. 23 n''est divisible que par 1 et lui-même.","difficulty":45,"status":"published","payload":{"decimals":0,"allow_negative":false},"answer":{"value":23,"tolerance":0}},{"external_key":"calc-022","concept_id":"calc.number_logic.multiples_7","concept_label":"Multiples de 7 jusqu''à 100","type":"numeric","prompt":"Combien de nombres entre 1 et 100 sont divisibles par 7 ?","explanation":"7 × 14 = 98 ≤ 100 et 7 × 15 = 105 > 100. Il y en a donc 14.","difficulty":60,"status":"published","payload":{"decimals":0,"allow_negative":false},"answer":{"value":14,"tolerance":0}},{"external_key":"calc-023","concept_id":"calc.number_logic.neg_times_neg","concept_label":"Produit de deux négatifs","type":"true_false","prompt":"Le produit de deux nombres négatifs est négatif.","explanation":"Moins par moins donne plus : (−3) × (−4) = 12.","difficulty":25,"status":"published","payload":{},"answer":{"value":false}},{"external_key":"calc-101","concept_id":"calc.mental.mult_12x15","concept_label":"12 × 15","type":"numeric","prompt":"Combien font 12 × 15 ?","explanation":"12 × 15 = 12 × 10 + 12 × 5 = 120 + 60 = 180.","difficulty":38,"status":"published","payload":{"decimals":0,"allow_negative":false},"answer":{"value":180,"tolerance":0}},{"external_key":"calc-102","concept_id":"calc.mental.mult_99x7","concept_label":"99 × 7","type":"numeric","prompt":"Combien font 99 × 7 ?","explanation":"99 × 7 = 100 × 7 − 7 = 700 − 7 = 693.","takeaway":"× 99 : on multiplie par 100 puis on retire une fois le nombre.","difficulty":45,"status":"published","payload":{"decimals":0,"allow_negative":false},"answer":{"value":693,"tolerance":0}},{"external_key":"calc-103","concept_id":"calc.mental.add_chain","concept_label":"Addition en chaîne","type":"numeric","prompt":"Combien font 48 + 37 + 52 + 63 ?","explanation":"On regroupe les compléments : (48 + 52) + (37 + 63) = 100 + 100 = 200.","takeaway":"Chercher les paires qui font 100 simplifie les additions.","difficulty":35,"status":"published","payload":{"decimals":0,"allow_negative":false},"answer":{"value":200,"tolerance":0}},{"external_key":"calc-104","concept_id":"calc.mental.div_144_12","concept_label":"144 ÷ 12","type":"numeric","prompt":"Combien font 144 ÷ 12 ?","explanation":"12 × 12 = 144, donc 144 ÷ 12 = 12. 144 s''appelle aussi une grosse (douze douzaines).","difficulty":30,"status":"published","payload":{"decimals":0,"allow_negative":false},"answer":{"value":12,"tolerance":0}},{"external_key":"calc-105","concept_id":"calc.mental.square_25","concept_label":"25 au carré","type":"numeric","prompt":"Combien vaut 25² ?","explanation":"2 × 3 = 6, puis on accole 25 : 625.","difficulty":42,"status":"published","payload":{"decimals":0,"allow_negative":false},"answer":{"value":625,"tolerance":0}},{"external_key":"calc-106","concept_id":"calc.mental.cube_4","concept_label":"4 au cube","type":"numeric","prompt":"Combien vaut 4³ ?","explanation":"4 × 4 × 4 = 16 × 4 = 64.","difficulty":40,"status":"published","payload":{"decimals":0,"allow_negative":false},"answer":{"value":64,"tolerance":0}},{"external_key":"calc-107","concept_id":"calc.mental.power_2_10","concept_label":"2 puissance 10","type":"numeric","prompt":"Combien vaut 2¹⁰ ?","explanation":"2, 4, 8, 16, 32, 64, 128, 256, 512, 1 024.","takeaway":"2¹⁰ = 1 024 : c''est pourquoi un kibioctet vaut 1 024 octets.","difficulty":55,"status":"published","payload":{"decimals":0,"allow_negative":false},"answer":{"value":1024,"tolerance":0}},{"external_key":"calc-108","concept_id":"calc.mental.half_of_odd","concept_label":"Moitié de 37","type":"numeric","prompt":"Quelle est la moitié de 37 ?","explanation":"La moitié de 36 est 18, et la moitié de 1 est 0,5 : 18,5.","difficulty":25,"status":"published","payload":{"decimals":1,"allow_negative":false},"answer":{"value":18.5,"tolerance":0}},{"external_key":"calc-109","concept_id":"calc.mental.priority_ops","concept_label":"Priorité des opérations","type":"numeric","prompt":"Combien font 2 + 3 × 4 ?","explanation":"La multiplication passe avant l''addition : 3 × 4 = 12, puis 2 + 12 = 14 (et non 20).","takeaway":"× et ÷ avant + et −, sauf parenthèses.","difficulty":40,"status":"published","payload":{"decimals":0,"allow_negative":false},"answer":{"value":14,"tolerance":0}},{"external_key":"calc-110","concept_id":"calc.mental.priority_ops_2","concept_label":"Priorité avec soustraction","type":"true_false","prompt":"10 − 2 × 3 = 24.","explanation":"On calcule d''abord 2 × 3 = 6, puis 10 − 6 = 4.","difficulty":45,"status":"published","payload":{},"answer":{"value":false}},{"external_key":"calc-111","concept_id":"calc.percent.half_is_50","concept_label":"Moitié en pourcentage","type":"numeric","prompt":"Combien font 50 % de 86 ?","explanation":"50 %, c''est la moitié : 86 ÷ 2 = 43.","difficulty":22,"status":"published","payload":{"decimals":0,"allow_negative":false},"answer":{"value":43,"tolerance":0}},{"external_key":"calc-112","concept_id":"calc.percent.vat_20","concept_label":"TVA à 20 %","type":"numeric","prompt":"Un article coûte 50 € hors taxes. Avec une TVA de 20 %, quel est son prix ?","explanation":"20 % de 50 = 10. 50 + 10 = 60 €. C''est aussi 50 × 1,2.","difficulty":50,"status":"published","payload":{"decimals":0,"unit":"€","allow_negative":false},"answer":{"value":60,"tolerance":0}},{"external_key":"calc-113","concept_id":"calc.percent.reverse_discount","concept_label":"Prix avant remise","type":"numeric","prompt":"Après une remise de 20 %, un article coûte 40 €. Quel était son prix initial ?","explanation":"Après −20 %, il reste 80 % du prix. 40 ÷ 0,8 = 50 €. Ajouter 20 % à 40 donnerait 48 € : c''est faux.","takeaway":"Pour annuler une baisse, on divise, on n''ajoute pas le même pourcentage.","difficulty":65,"status":"published","payload":{"decimals":0,"unit":"€","allow_negative":false},"answer":{"value":50,"tolerance":0}},{"external_key":"calc-114","concept_id":"calc.percent.double","concept_label":"Doubler en pourcentage","type":"mcq","prompt":"Un prix double. De quel pourcentage a-t-il augmenté ?","explanation":"Doubler, c''est ajouter 100 % du prix initial. +200 % reviendrait à tripler.","difficulty":48,"status":"published","payload":{"options":[{"id":"676fb7e1","text":"100 %"},{"id":"2d8e9b22","text":"200 %"},{"id":"b23af74c","text":"50 %"},{"id":"fcf80837","text":"2 %"}]},"answer":{"option_id":"676fb7e1"}},{"external_key":"calc-115","concept_id":"calc.fractions.compare","concept_label":"Comparer des fractions","type":"mcq","prompt":"Quelle est la plus grande fraction ?","explanation":"En décimal : 3/5 = 0,6 ; 4/7 ≈ 0,571 ; 5/9 ≈ 0,556 ; 2/4 = 0,5.","difficulty":45,"status":"published","payload":{"options":[{"id":"938d0f8c","text":"3/5"},{"id":"486912ca","text":"4/7"},{"id":"13b94c06","text":"5/9"},{"id":"84ab2330","text":"2/4"}]},"answer":{"option_id":"938d0f8c"}},{"external_key":"calc-116","concept_id":"calc.fractions.of_quantity","concept_label":"Trois quarts de 60","type":"numeric","prompt":"Combien font les trois quarts de 60 ?","explanation":"Un quart de 60 = 15, donc trois quarts = 45.","difficulty":35,"status":"published","payload":{"decimals":0,"allow_negative":false},"answer":{"value":45,"tolerance":0}},{"external_key":"calc-117","concept_id":"calc.fractions.order","concept_label":"Ranger des fractions","type":"ordering","prompt":"Range ces nombres du plus petit au plus grand.","explanation":"1/8 = 0,125 ; 0,2 ; 1/4 = 0,25 ; 0,3.","difficulty":55,"status":"published","payload":{"items":[{"id":"24909423","text":"1/8"},{"id":"a425d292","text":"0,2"},{"id":"83c23dc3","text":"1/4"},{"id":"929a5275","text":"0,3"}]},"answer":{"order":["24909423","a425d292","83c23dc3","929a5275"]}},{"external_key":"calc-118","concept_id":"calc.conversions.minutes_day","concept_label":"Minutes dans une journée","type":"numeric","prompt":"Combien y a-t-il de minutes dans une journée ?","explanation":"24 heures × 60 minutes = 1 440 minutes.","difficulty":45,"status":"published","payload":{"decimals":0,"allow_negative":false},"answer":{"value":1440,"tolerance":0}},{"external_key":"calc-119","concept_id":"calc.conversions.kmh_ms","concept_label":"km/h en m/s","type":"numeric","prompt":"36 km/h, cela fait combien de mètres par seconde ?","explanation":"36 km/h = 36 000 m en 3 600 s = 10 m/s. On divise par 3,6.","takeaway":"km/h ÷ 3,6 = m/s.","difficulty":60,"status":"published","payload":{"decimals":0,"unit":"m/s","allow_negative":false},"answer":{"value":10,"tolerance":0}},{"external_key":"calc-120","concept_id":"calc.conversions.units_pairs","concept_label":"Unités équivalentes","type":"pairs","prompt":"Associe chaque quantité à son équivalent.","explanation":"Une tonne = 1 000 kg ; un are = 100 m² (un carré de 10 m de côté) ; un décilitre = 100 mL ; une heure = 3 600 s.","difficulty":45,"status":"published","payload":{"left":[{"id":"4baa3445","text":"1 tonne"},{"id":"9a2e4285","text":"1 are"},{"id":"d03b8eaf","text":"1 décilitre"},{"id":"fbe19267","text":"1 heure"}],"right":[{"id":"f8f5ef23","text":"1 000 kg"},{"id":"d3514185","text":"100 m²"},{"id":"8d41cfd5","text":"100 mL"},{"id":"d187a3a4","text":"3 600 s"}]},"answer":{"pairs":{"4baa3445":"f8f5ef23","9a2e4285":"d3514185","d03b8eaf":"8d41cfd5","fbe19267":"d187a3a4"}}},{"external_key":"calc-121","concept_id":"calc.conversions.dozen_score","concept_label":"Douzaines","type":"numeric","prompt":"Combien d''œufs y a-t-il dans trois douzaines ?","explanation":"Une douzaine = 12. 3 × 12 = 36.","difficulty":25,"status":"published","payload":{"decimals":0,"allow_negative":false},"answer":{"value":36,"tolerance":0}},{"external_key":"calc-122","concept_id":"calc.number_logic.average","concept_label":"Moyenne de trois notes","type":"numeric","prompt":"Quelle est la moyenne de 12, 15 et 18 ?","explanation":"(12 + 15 + 18) ÷ 3 = 45 ÷ 3 = 15.","difficulty":40,"status":"published","payload":{"decimals":0,"allow_negative":false},"answer":{"value":15,"tolerance":0}},{"external_key":"calc-123","concept_id":"calc.number_logic.divisible_by_3","concept_label":"Divisibilité par 3","type":"true_false","prompt":"Le nombre 123 456 est divisible par 3.","explanation":"Un nombre est divisible par 3 si la somme de ses chiffres l''est : 1+2+3+4+5+6 = 21, divisible par 3.","takeaway":"Divisible par 3 (ou 9) ⇔ somme des chiffres divisible par 3 (ou 9).","difficulty":50,"status":"published","payload":{},"answer":{"value":true}},{"external_key":"calc-124","concept_id":"calc.number_logic.roman_numerals","concept_label":"Chiffres romains","type":"mcq","prompt":"Comment écrit-on 1 999 en chiffres romains ?","explanation":"1000 = M, 900 = CM, 90 = XC, 9 = IX : MCMXCIX. « MIM » est une abréviation fautive.","difficulty":45,"status":"published","payload":{"options":[{"id":"638b82c7","text":"MCMXCIX"},{"id":"e5563476","text":"MIM"},{"id":"8be7e282","text":"MDCCCCLXXXXVIIII"},{"id":"149ff4d0","text":"MCMIC"}]},"answer":{"option_id":"638b82c7"}},{"external_key":"calc-125","concept_id":"calc.number_logic.gcd","concept_label":"PGCD","type":"numeric","prompt":"Quel est le plus grand diviseur commun de 24 et 36 ?","explanation":"Diviseurs communs : 1, 2, 3, 4, 6, 12. Le plus grand est 12.","difficulty":55,"status":"published","payload":{"decimals":0,"allow_negative":false},"answer":{"value":12,"tolerance":0}},{"external_key":"fr-001","concept_id":"french.vocabulary.pusillanime","concept_label":"Pusillanime","type":"mcq","prompt":"Que signifie « pusillanime » ?","explanation":"Du latin pusillus (tout petit) et animus (esprit) : qui a « l''âme petite », craintif, sans audace.","takeaway":"Son contraire : magnanime (« à la grande âme »).","difficulty":62,"status":"published","payload":{"options":[{"id":"7ab6dcd2","text":"Qui manque de courage"},{"id":"00fb8a5d","text":"Très petit"},{"id":"a32f01e2","text":"D''une grande générosité"},{"id":"fcd1fc9a","text":"Qui parle beaucoup"}]},"answer":{"option_id":"7ab6dcd2"}},{"external_key":"fr-002","concept_id":"french.vocabulary.procrastiner","concept_label":"Procrastiner","type":"mcq","prompt":"« Procrastiner », c''est…","explanation":"Du latin cras, « demain » : procrastiner, c''est repousser à plus tard ce qu''on pourrait faire maintenant.","difficulty":32,"status":"published","payload":{"options":[{"id":"463a345e","text":"remettre au lendemain"},{"id":"b6f2fea8","text":"parler en public"},{"id":"22637c39","text":"critiquer sans cesse"},{"id":"e60094b4","text":"prévoir à l''avance"}]},"answer":{"option_id":"463a345e"}},{"external_key":"fr-003","concept_id":"french.vocabulary.diatribe","concept_label":"Diatribe","type":"mcq","prompt":"Une « diatribe » est…","explanation":"Une diatribe est un discours ou un écrit qui attaque avec violence une personne ou une idée.","difficulty":55,"status":"published","payload":{"options":[{"id":"1d17460a","text":"une critique violente"},{"id":"2825de38","text":"un long voyage"},{"id":"8e765074","text":"une maladie respiratoire"},{"id":"441eb103","text":"un instrument à vent"}]},"answer":{"option_id":"1d17460a"}},{"external_key":"fr-004","concept_id":"french.vocabulary.obsolete","concept_label":"Obsolète","type":"mcq","prompt":"Un appareil « obsolète » est…","explanation":"Obsolète : qui n''est plus en usage, périmé, remplacé par quelque chose de plus récent.","difficulty":32,"status":"published","payload":{"options":[{"id":"c76c3127","text":"dépassé"},{"id":"5771e611","text":"neuf"},{"id":"bc8e65ff","text":"fragile"},{"id":"7877d765","text":"coûteux"}]},"answer":{"option_id":"c76c3127"}},{"external_key":"fr-005","concept_id":"french.vocabulary.ubuesque","concept_label":"Ubuesque","type":"mcq","prompt":"Une situation « ubuesque » est…","explanation":"L''adjectif vient d''Ubu roi (1896), pièce d''Alfred Jarry dont le héros est un tyran cruel et ridicule.","takeaway":"Ubuesque = absurde au point d''en être comique.","difficulty":58,"status":"published","payload":{"options":[{"id":"86f19728","text":"absurde et grotesque"},{"id":"48daa7bd","text":"très ancienne"},{"id":"52bd8d71","text":"d''une grande beauté"},{"id":"4ee5396a","text":"parfaitement organisée"}]},"answer":{"option_id":"86f19728"}},{"external_key":"fr-006","concept_id":"french.synonyms.loquace","concept_label":"Synonyme de loquace","type":"mcq","prompt":"Quel est le synonyme de « loquace » ?","explanation":"Loquace (du latin loqui, « parler ») : qui parle volontiers et beaucoup.","difficulty":45,"status":"published","payload":{"options":[{"id":"67c0763e","text":"bavard"},{"id":"e8884c1b","text":"silencieux"},{"id":"8a55ee26","text":"rapide"},{"id":"9e59d02f","text":"généreux"}]},"answer":{"option_id":"67c0763e"}},{"external_key":"fr-007","concept_id":"french.synonyms.ephemere","concept_label":"Synonyme d''éphémère","type":"mcq","prompt":"Quel mot est le plus proche de « éphémère » ?","explanation":"Éphémère vient du grec « qui ne dure qu''un jour » : qui est de courte durée.","takeaway":"L''éphémère est aussi un insecte dont l''adulte ne vit que quelques heures.","difficulty":32,"status":"published","payload":{"options":[{"id":"eb97cede","text":"passager"},{"id":"ebb222b8","text":"éternel"},{"id":"fa0290f4","text":"immense"},{"id":"65b34f82","text":"fragile"}]},"answer":{"option_id":"eb97cede"}},{"external_key":"fr-008","concept_id":"french.antonyms.prolixe","concept_label":"Contraire de prolixe","type":"mcq","prompt":"Quel est le contraire de « prolixe » ?","explanation":"Prolixe : qui s''exprime trop longuement. Son contraire est concis : qui dit beaucoup en peu de mots.","difficulty":60,"status":"published","payload":{"options":[{"id":"0e95bdc4","text":"concis"},{"id":"0533625e","text":"bavard"},{"id":"ab0b8b69","text":"abondant"},{"id":"450e0142","text":"confus"}]},"answer":{"option_id":"0e95bdc4"}},{"external_key":"fr-009","concept_id":"french.antonyms.altruiste","concept_label":"Contraire d''altruiste","type":"mcq","prompt":"Quel est le contraire de « altruiste » ?","explanation":"L''altruiste se soucie des autres (latin alter, « autre ») ; l''égoïste de lui-même (ego, « moi »).","difficulty":28,"status":"published","payload":{"options":[{"id":"6cd67420","text":"égoïste"},{"id":"1bfaacab","text":"généreux"},{"id":"30fae682","text":"timide"},{"id":"ca16c6c5","text":"naïf"}]},"answer":{"option_id":"6cd67420"}},{"external_key":"fr-010","concept_id":"french.spelling.occurrence","concept_label":"Occurrence","type":"mcq","prompt":"Quelle orthographe est correcte ?","explanation":"Occurrence prend deux c et deux r, comme le latin occurrere (« se présenter »).","takeaway":"Même famille : concurrence, deux c, deux r.","difficulty":55,"status":"published","payload":{"options":[{"id":"c4107216","text":"occurrence"},{"id":"f757bc50","text":"occurence"},{"id":"44a9f9db","text":"ocurrence"},{"id":"736c62ca","text":"occurrance"}]},"answer":{"option_id":"c4107216"}},{"external_key":"fr-011","concept_id":"french.spelling.se_rendre_compte","concept_label":"Se rendre compte","type":"mcq","prompt":"Complète : « Elles se sont ___ compte de leur erreur. »","explanation":"Le complément d''objet direct est « compte », placé après le verbe : le participe reste invariable.","takeaway":"« Elles se sont rendu compte », toujours sans accord.","difficulty":65,"status":"published","payload":{"options":[{"id":"9ff87dea","text":"rendu"},{"id":"de98cd2d","text":"rendues"},{"id":"4f10cdf3","text":"rendus"},{"id":"86a7de2a","text":"rendue"}]},"answer":{"option_id":"9ff87dea"}},{"external_key":"fr-012","concept_id":"french.spelling.parmi","concept_label":"Parmi","type":"true_false","prompt":"« Parmis », avec un s, est une orthographe acceptée.","explanation":"« Parmi » ne prend jamais de s, contrairement à « hormis » ou « jadis ».","takeaway":"Parmi s''écrit toujours sans s.","difficulty":45,"status":"published","payload":{},"answer":{"value":false}},{"external_key":"fr-013","concept_id":"french.spelling.plural_chou","concept_label":"Pluriel de chou","type":"mcq","prompt":"Quel est le pluriel de « un chou » ?","explanation":"Sept noms en -ou prennent un x au pluriel : bijou, caillou, chou, genou, hibou, joujou, pou.","difficulty":28,"status":"published","payload":{"options":[{"id":"85b872f5","text":"des choux"},{"id":"95169388","text":"des chous"},{"id":"970e64d6","text":"des chouxs"},{"id":"36a32c99","text":"des chou"}]},"answer":{"option_id":"85b872f5"}},{"external_key":"fr-014","concept_id":"french.expressions.poser_lapin","concept_label":"Poser un lapin","type":"mcq","prompt":"« Poser un lapin » à quelqu''un, c''est…","explanation":"L''expression apparaît au XIXe siècle : « poser un lapin » voulait d''abord dire partir sans payer ce qu''on devait.","difficulty":22,"status":"published","payload":{"options":[{"id":"6ba9a6b6","text":"ne pas venir à un rendez-vous"},{"id":"0cf1fe1a","text":"lui faire une farce"},{"id":"bf7fedd2","text":"lui offrir un cadeau"},{"id":"5170aa1b","text":"partir sans payer"}]},"answer":{"option_id":"6ba9a6b6"}},{"external_key":"fr-015","concept_id":"french.expressions.avoir_cafard","concept_label":"Avoir le cafard","type":"mcq","prompt":"« Avoir le cafard » signifie…","explanation":"Le cafard, insecte sombre qui fuit la lumière, a fini par désigner les idées noires.","difficulty":28,"status":"published","payload":{"options":[{"id":"bcc3231a","text":"être triste, déprimé"},{"id":"35cb970c","text":"avoir peur"},{"id":"309e4cc5","text":"être malade"},{"id":"2a44c442","text":"avoir faim"}]},"answer":{"option_id":"bcc3231a"}},{"external_key":"fr-016","concept_id":"french.expressions.sur_la_sellette","concept_label":"Être sur la sellette","type":"mcq","prompt":"« Être sur la sellette » signifie…","explanation":"La sellette était le petit siège où l''on faisait asseoir un accusé pour l''interroger.","difficulty":55,"status":"published","payload":{"options":[{"id":"820ad737","text":"être mis en cause, sur le point d''être jugé"},{"id":"95e7bbe1","text":"être en vacances"},{"id":"a621eff7","text":"être le favori"},{"id":"644321e5","text":"être assis au premier rang"}]},"answer":{"option_id":"820ad737"}},{"external_key":"fr-017","concept_id":"french.expressions.couper_poire","concept_label":"Couper la poire en deux","type":"mcq","prompt":"« Couper la poire en deux », c''est…","explanation":"Chacun fait la moitié du chemin : on partage les concessions à parts égales.","difficulty":28,"status":"published","payload":{"options":[{"id":"e7e6373b","text":"faire un compromis"},{"id":"fba04485","text":"partager un repas"},{"id":"beba2a37","text":"mentir à moitié"},{"id":"078aba94","text":"abandonner un projet"}]},"answer":{"option_id":"e7e6373b"}},{"external_key":"fr-018","concept_id":"french.grammar.coi_lui","concept_label":"Fonction de « lui »","type":"mcq","prompt":"Dans « Je le lui ai donné », quelle est la fonction de « lui » ?","explanation":"On donne quelque chose (le = COD) à quelqu''un (lui = à lui, COI).","difficulty":55,"status":"published","payload":{"options":[{"id":"3430cee0","text":"complément d''objet indirect"},{"id":"39f0ea10","text":"complément d''objet direct"},{"id":"73ff8f4b","text":"sujet"},{"id":"1496b03e","text":"attribut du sujet"}]},"answer":{"option_id":"3430cee0"}},{"external_key":"fr-019","concept_id":"french.grammar.quoi_que","concept_label":"Quoi que / quoique","type":"mcq","prompt":"Complète : « ___ tu fasses, je t''aiderai. »","explanation":"« Quoi que » en deux mots signifie « quelle que soit la chose que ». « Quoique » en un mot signifie « bien que ».","takeaway":"Si on peut dire « bien que », c''est quoique.","difficulty":60,"status":"published","payload":{"options":[{"id":"d16ce082","text":"Quoi que"},{"id":"e94e110a","text":"Quoique"},{"id":"140bbc77","text":"Quoiqu''"},{"id":"3c2741f0","text":"Quoi qu''"}]},"answer":{"option_id":"d16ce082"}},{"external_key":"fr-020","concept_id":"french.grammar.adverbe_bien","concept_label":"Nature de « bien »","type":"mcq","prompt":"Dans « Il chante bien », quelle est la nature de « bien » ?","explanation":"« Bien » précise la manière de chanter : il modifie un verbe, c''est un adverbe.","difficulty":35,"status":"published","payload":{"options":[{"id":"e730e3cf","text":"adverbe"},{"id":"c1abc783","text":"adjectif"},{"id":"fbdd212b","text":"nom"},{"id":"c069e1be","text":"préposition"}]},"answer":{"option_id":"e730e3cf"}},{"external_key":"fr-021","concept_id":"french.synonyms.pairs_set1","concept_label":"Synonymes : onéreux, fugace…","type":"pairs","prompt":"Associe chaque mot à son synonyme.","explanation":"Onéreux : qui coûte cher. Fugace : qui dure peu. Opiniâtre : qui persévère. Candide : d''une innocence naïve (comme le héros de Voltaire).","difficulty":55,"status":"published","payload":{"left":[{"id":"08787b43","text":"Onéreux"},{"id":"72325c48","text":"Fugace"},{"id":"e8451367","text":"Opiniâtre"},{"id":"77460fa5","text":"Candide"}],"right":[{"id":"07adf531","text":"Coûteux"},{"id":"4753e6db","text":"Bref"},{"id":"fa71270a","text":"Tenace"},{"id":"f652e8a8","text":"Naïf"}]},"answer":{"pairs":{"08787b43":"07adf531","72325c48":"4753e6db","e8451367":"fa71270a","77460fa5":"f652e8a8"}}},{"external_key":"fr-101","concept_id":"french.spelling.acquerir_pp","concept_label":"Participe passé d''acquérir","type":"mcq","prompt":"Quel est le participe passé du verbe « acquérir » ?","explanation":"On écrit « acquis » : « un avantage acquis ». « Acquit » existe, mais c''est un nom : « par acquit de conscience ».","difficulty":55,"status":"published","payload":{"options":[{"id":"c6094ce9","text":"acquis"},{"id":"73f72cc9","text":"acquéri"},{"id":"720d5c8f","text":"acquit"},{"id":"bb79a070","text":"acquérit"}]},"answer":{"option_id":"c6094ce9"}},{"external_key":"fr-102","concept_id":"french.spelling.malgre_que","concept_label":"Malgré que","type":"true_false","prompt":"Selon l''usage soutenu, il vaut mieux écrire « bien qu''il pleuve » que « malgré qu''il pleuve ».","explanation":"« Malgré que » est critiqué par l''Académie française, sauf dans « malgré qu''il en ait ». On préfère « bien que » ou « quoique ».","difficulty":60,"status":"published","payload":{},"answer":{"value":true}},{"external_key":"fr-103","concept_id":"french.spelling.plural_bijou","concept_label":"Pluriel de bijou","type":"true_false","prompt":"Le pluriel de « bijou » est « bijoux ».","explanation":"Bijou fait partie des sept noms en -ou qui prennent un x : bijou, caillou, chou, genou, hibou, joujou, pou.","difficulty":25,"status":"published","payload":{},"answer":{"value":true}},{"external_key":"fr-104","concept_id":"french.spelling.plural_festival","concept_label":"Pluriel de festival","type":"mcq","prompt":"Quel est le pluriel de « festival » ?","explanation":"La plupart des noms en -al font -aux, mais quelques-uns font -als : bal, carnaval, chacal, festival, récital, régal.","difficulty":45,"status":"published","payload":{"options":[{"id":"21cca93a","text":"festivals"},{"id":"4737d66e","text":"festivaux"},{"id":"39ecf103","text":"festivales"},{"id":"79d85729","text":"festivaus"}]},"answer":{"option_id":"21cca93a"}},{"external_key":"fr-105","concept_id":"french.spelling.a_accent","concept_label":"a ou à","type":"mcq","prompt":"Complète : « Il ___ pris le train ___ huit heures. »","explanation":"« a » est le verbe avoir (on peut dire « avait »). « à » est une préposition.","takeaway":"Si « avait » fonctionne, on écrit « a » sans accent.","difficulty":22,"status":"published","payload":{"options":[{"id":"1d5f7b88","text":"a / à"},{"id":"06ed9c93","text":"à / a"},{"id":"01a72339","text":"a / a"},{"id":"da74e9d8","text":"à / à"}]},"answer":{"option_id":"1d5f7b88"}},{"external_key":"fr-106","concept_id":"french.spelling.quelque_fois","concept_label":"Quelquefois / quelques fois","type":"mcq","prompt":"Complète : « Je vais ___ au cinéma. » (= parfois)","explanation":"En un mot, « quelquefois » signifie « parfois ». « Quelques fois » signifie « un petit nombre de fois ».","difficulty":58,"status":"published","payload":{"options":[{"id":"9a100abb","text":"quelquefois"},{"id":"f4edbbf8","text":"quelques fois"},{"id":"61241dd6","text":"quelque fois"},{"id":"e7b1ce65","text":"quelques-fois"}]},"answer":{"option_id":"9a100abb"}},{"external_key":"fr-107","concept_id":"french.vocabulary.meme_sens_pairs","concept_label":"Sens de mots rares","type":"pairs","prompt":"Associe chaque mot à sa définition.","explanation":"Péremptoire : tranchant. Sibyllin vient des sibylles, prophétesses aux oracles obscurs. Velléitaire : qui a des velléités sans les réaliser. Laconique vient de Laconie, région des Spartiates, réputés pour parler peu.","difficulty":60,"status":"published","payload":{"left":[{"id":"e48fc041","text":"Péremptoire"},{"id":"61e2e81a","text":"Sibyllin"},{"id":"e0ba7303","text":"Velléitaire"},{"id":"5ace6734","text":"Laconique"}],"right":[{"id":"42305462","text":"Qui n''admet pas la réplique"},{"id":"30b69537","text":"Obscur, énigmatique"},{"id":"5d748ea3","text":"Qui ne va pas au bout de ses intentions"},{"id":"cf093302","text":"Qui s''exprime en peu de mots"}]},"answer":{"pairs":{"e48fc041":"42305462","61e2e81a":"30b69537","e0ba7303":"5d748ea3","5ace6734":"cf093302"}}},{"external_key":"fr-108","concept_id":"french.vocabulary.affable","concept_label":"Affable","type":"mcq","prompt":"Une personne « affable » est…","explanation":"Affable vient du latin affabilis, « à qui l''on peut parler » : d''un abord agréable.","difficulty":45,"status":"published","payload":{"options":[{"id":"89658f03","text":"aimable et accueillante"},{"id":"6af7f6e7","text":"très bavarde"},{"id":"8a2a2ff4","text":"facile à tromper"},{"id":"bbd04940","text":"toujours affamée"}]},"answer":{"option_id":"89658f03"}},{"external_key":"fr-109","concept_id":"french.vocabulary.hapax_alacrite","concept_label":"Alacrité","type":"mcq","prompt":"Faire quelque chose « avec alacrité », c''est le faire…","explanation":"L''alacrité est une vivacité enjouée. Le mot vient du latin alacer, « vif, allègre ».","difficulty":65,"status":"published","payload":{"options":[{"id":"981af7ba","text":"avec un entrain joyeux"},{"id":"fe2a566f","text":"avec lenteur"},{"id":"e266fba8","text":"avec méfiance"},{"id":"5c7b4d82","text":"avec amertume"}]},"answer":{"option_id":"981af7ba"}},{"external_key":"fr-110","concept_id":"french.vocabulary.paronymes_pairs","concept_label":"Paronymes","type":"pairs","prompt":"Associe chaque mot à son sens.","explanation":"Ces paires se ressemblent sans avoir le même sens : ce sont des paronymes. Une conjoncture économique, une simple conjecture.","difficulty":55,"status":"published","payload":{"left":[{"id":"82d9ed0c","text":"Éminent"},{"id":"29525cac","text":"Imminent"},{"id":"134dc9ba","text":"Conjecture"},{"id":"c941f74f","text":"Conjoncture"}],"right":[{"id":"cfbcf425","text":"Remarquable"},{"id":"ac3817f3","text":"Sur le point d''arriver"},{"id":"0bb051ef","text":"Hypothèse"},{"id":"dd07fc7a","text":"Situation du moment"}]},"answer":{"pairs":{"82d9ed0c":"cfbcf425","29525cac":"ac3817f3","134dc9ba":"0bb051ef","c941f74f":"dd07fc7a"}}},{"external_key":"fr-111","concept_id":"french.synonyms.onereux_rapide","concept_label":"Synonyme de fortuit","type":"mcq","prompt":"Quel est le synonyme de « fortuit » ?","explanation":"Fortuit : qui arrive par hasard. Une rencontre fortuite n''était pas prévue.","difficulty":50,"status":"published","payload":{"options":[{"id":"32265770","text":"accidentel"},{"id":"3c936a72","text":"volontaire"},{"id":"eacfb19b","text":"fortifié"},{"id":"1e93b65d","text":"heureux"}]},"answer":{"option_id":"32265770"}},{"external_key":"fr-112","concept_id":"french.antonyms.prodigue","concept_label":"Contraire de prodigue","type":"mcq","prompt":"Quel est le contraire de « prodigue » ?","explanation":"Prodigue : qui dépense sans compter (l''enfant prodigue de la Bible). L''avare, lui, retient tout.","difficulty":50,"status":"published","payload":{"options":[{"id":"88486f90","text":"avare"},{"id":"5a39a9d7","text":"généreux"},{"id":"c344f9a3","text":"doué"},{"id":"c555161f","text":"pauvre"}]},"answer":{"option_id":"88486f90"}},{"external_key":"fr-113","concept_id":"french.antonyms.ephemere_perenne","concept_label":"Contraire d''éphémère","type":"mcq","prompt":"Quel mot est le contraire de « éphémère » ?","explanation":"Pérenne : qui dure longtemps, voire toujours. Passager et fugace sont des synonymes d''éphémère.","difficulty":55,"status":"published","payload":{"options":[{"id":"e80a42ec","text":"pérenne"},{"id":"6c4db19e","text":"passager"},{"id":"86c06f18","text":"fugace"},{"id":"0bf99e0a","text":"précaire"}]},"answer":{"option_id":"e80a42ec"}},{"external_key":"fr-114","concept_id":"french.expressions.origins_pairs","concept_label":"Expressions et sens","type":"pairs","prompt":"Associe chaque expression à son sens.","explanation":"Les nues sont les nuages : on tombe de très haut. « Faire chou blanc » viendrait du jeu de quilles, où « coup » se prononçait « chou » en Berry.","difficulty":40,"status":"published","payload":{"left":[{"id":"0178fd16","text":"Tomber des nues"},{"id":"22716de7","text":"Mettre la puce à l''oreille"},{"id":"8688efd2","text":"Avoir un poil dans la main"},{"id":"1cc48149","text":"Faire chou blanc"}],"right":[{"id":"f6e64911","text":"Être très surpris"},{"id":"627e016d","text":"Éveiller un soupçon"},{"id":"372c8bd5","text":"Être paresseux"},{"id":"2f564e33","text":"Échouer"}]},"answer":{"pairs":{"0178fd16":"f6e64911","22716de7":"627e016d","8688efd2":"372c8bd5","1cc48149":"2f564e33"}}},{"external_key":"fr-115","concept_id":"french.expressions.monts_merveilles","concept_label":"Promettre monts et merveilles","type":"mcq","prompt":"« Promettre monts et merveilles », c''est…","explanation":"On promet des avantages considérables, souvent sans pouvoir les tenir.","difficulty":30,"status":"published","payload":{"options":[{"id":"8b113642","text":"promettre des choses extraordinaires"},{"id":"0e2268db","text":"faire un long voyage"},{"id":"257d9732","text":"mentir sur son âge"},{"id":"f91f6f8b","text":"offrir un tableau"}]},"answer":{"option_id":"8b113642"}},{"external_key":"fr-116","concept_id":"french.expressions.fil_a_retordre","concept_label":"Donner du fil à retordre","type":"mcq","prompt":"« Donner du fil à retordre » à quelqu''un, c''est…","explanation":"Retordre le fil (le tordre à nouveau pour le renforcer) était un travail long et pénible.","difficulty":35,"status":"published","payload":{"options":[{"id":"79929421","text":"lui causer des difficultés"},{"id":"cc2d9a26","text":"lui apprendre la couture"},{"id":"0c2719c7","text":"lui faire un cadeau"},{"id":"8983f238","text":"le tromper"}]},"answer":{"option_id":"79929421"}},{"external_key":"fr-117","concept_id":"french.grammar.subjonctif_bien_que","concept_label":"Mode après bien que","type":"mcq","prompt":"Complète : « Bien qu''il ___ tard, nous sortirons. »","explanation":"« Bien que » est toujours suivi du subjonctif.","difficulty":50,"status":"published","payload":{"options":[{"id":"420b6c61","text":"soit"},{"id":"4cdd5ead","text":"est"},{"id":"0d42932a","text":"sera"},{"id":"addf2f27","text":"serait"}]},"answer":{"option_id":"420b6c61"}},{"external_key":"fr-118","concept_id":"french.grammar.apres_que","concept_label":"Mode après après que","type":"true_false","prompt":"Selon la règle, on écrit « après qu''il est parti » (indicatif) et non « après qu''il soit parti ».","explanation":"« Après que » exprime un fait accompli : il se construit avec l''indicatif. Le subjonctif est répandu à l''oral mais fautif selon la norme.","takeaway":"Avant que + subjonctif ; après que + indicatif.","difficulty":65,"status":"published","payload":{},"answer":{"value":true}},{"external_key":"fr-119","concept_id":"french.grammar.word_classes_pairs","concept_label":"Nature des mots","type":"pairs","prompt":"Dans « Le chat noir dort paisiblement », associe chaque mot à sa nature.","explanation":"« Le » détermine le nom « chat », « noir » le qualifie, « dort » est le verbe, « paisiblement » précise la manière.","difficulty":40,"status":"published","payload":{"left":[{"id":"484bc0f9","text":"Le"},{"id":"a9a79eb4","text":"noir"},{"id":"e84806a0","text":"dort"},{"id":"76828c46","text":"paisiblement"}],"right":[{"id":"c4d14dc6","text":"Déterminant"},{"id":"80c7e19e","text":"Adjectif"},{"id":"5d4871e4","text":"Verbe"},{"id":"ddc0aa6b","text":"Adverbe"}]},"answer":{"pairs":{"484bc0f9":"c4d14dc6","a9a79eb4":"80c7e19e","e84806a0":"5d4871e4","76828c46":"ddc0aa6b"}}},{"external_key":"fr-120","concept_id":"french.grammar.alphabetical_order","concept_label":"Ordre alphabétique","type":"ordering","prompt":"Range ces mots dans l''ordre du dictionnaire.","explanation":"On compare lettre à lettre : abr-i < abr-u, puis abs-o < abs-t.","difficulty":35,"status":"published","payload":{"items":[{"id":"720017c6","text":"abricot"},{"id":"6d06a3ef","text":"abrupt"},{"id":"2900f09d","text":"absolu"},{"id":"a9032861","text":"abstrait"}]},"answer":{"order":["720017c6","6d06a3ef","2900f09d","a9032861"]}},{"external_key":"fr-121","concept_id":"french.vocabulary.etymology_pairs","concept_label":"Racines grecques","type":"pairs","prompt":"Associe chaque racine grecque à son sens.","explanation":"Chronomètre (mesurer le temps), hydrater (l''eau), orthographe (écrire correctement), philosophie (l''amour de la sagesse).","difficulty":55,"status":"published","payload":{"left":[{"id":"3b2385bf","text":"Chrono-"},{"id":"9e774e90","text":"Hydro-"},{"id":"0e5dd1c4","text":"Graphie"},{"id":"4c0cc355","text":"Philo-"}],"right":[{"id":"fc47bc6c","text":"Temps"},{"id":"89487b0d","text":"Eau"},{"id":"92be6928","text":"Écriture"},{"id":"70ee254e","text":"Qui aime"}]},"answer":{"pairs":{"3b2385bf":"fc47bc6c","9e774e90":"89487b0d","0e5dd1c4":"92be6928","4c0cc355":"70ee254e"}}},{"external_key":"fr-122","concept_id":"french.spelling.accent_circonflexe","concept_label":"Accent circonflexe","type":"true_false","prompt":"L''accent circonflexe de « forêt » rappelle un s disparu, que l''on retrouve dans « forestier ».","explanation":"Le circonflexe marque souvent un ancien s : forêt/forestier, hôpital/hospitalier, fête/festival.","difficulty":55,"status":"published","payload":{},"answer":{"value":true}},{"external_key":"fr-123","concept_id":"french.vocabulary.pleonasme","concept_label":"Pléonasme","type":"mcq","prompt":"Laquelle de ces expressions est un pléonasme ?","explanation":"On ne peut monter qu''en haut : « en haut » répète l''idée. Idem pour « prévoir à l''avance ».","difficulty":45,"status":"published","payload":{"options":[{"id":"44f20a5c","text":"Monter en haut"},{"id":"3d553322","text":"Descendre vite"},{"id":"fcc84fa6","text":"Entrer doucement"},{"id":"6386e2aa","text":"Sortir tard"}]},"answer":{"option_id":"44f20a5c"}},{"external_key":"fr-124","concept_id":"french.grammar.conjugaison_passe_simple","concept_label":"Passé simple de venir","type":"mcq","prompt":"Complète au passé simple : « Ils ___ nous voir. »","explanation":"Venir au passé simple : je vins, tu vins, il vint, nous vînmes, vous vîntes, ils vinrent.","difficulty":50,"status":"published","payload":{"options":[{"id":"ae186688","text":"vinrent"},{"id":"a14f1240","text":"venirent"},{"id":"29180faa","text":"vinirent"},{"id":"4dbf092a","text":"venèrent"}]},"answer":{"option_id":"ae186688"}},{"external_key":"fr-125","concept_id":"french.synonyms.verbs_pairs","concept_label":"Synonymes de verbes","type":"pairs","prompt":"Associe chaque verbe à son synonyme.","explanation":"Entériner une décision, éluder une question, proscrire un usage, réfuter un argument.","difficulty":45,"status":"published","payload":{"left":[{"id":"753a22bf","text":"Entériner"},{"id":"10da1d41","text":"Éluder"},{"id":"c43af864","text":"Proscrire"},{"id":"2801f70c","text":"Réfuter"}],"right":[{"id":"71ac2fed","text":"Valider"},{"id":"14dea38e","text":"Esquiver"},{"id":"b2ee29a4","text":"Interdire"},{"id":"dbfcb526","text":"Contredire"}]},"answer":{"pairs":{"753a22bf":"71ac2fed","10da1d41":"14dea38e","c43af864":"b2ee29a4","2801f70c":"dbfcb526"}}},{"external_key":"geo-001","concept_id":"geography.capitals.australia","concept_label":"Capitale de l''Australie","type":"mcq","prompt":"Quelle est la capitale de l''Australie ?","explanation":"Canberra a été créée de toutes pièces au début du XXe siècle, en compromis entre les rivales Sydney et Melbourne.","takeaway":"Plusieurs capitales ne sont pas la plus grande ville du pays : Canberra, Ottawa, Brasília…","difficulty":40,"status":"published","payload":{"options":[{"id":"1539bf86","text":"Canberra"},{"id":"e9d8805f","text":"Sydney"},{"id":"eed18659","text":"Melbourne"},{"id":"7684571a","text":"Perth"}]},"answer":{"option_id":"1539bf86"}},{"external_key":"geo-002","concept_id":"geography.capitals.canada","concept_label":"Capitale du Canada","type":"mcq","prompt":"Quelle est la capitale du Canada ?","explanation":"Ottawa, en Ontario, à la limite du Québec, a été choisie en 1857 par la reine Victoria.","difficulty":35,"status":"published","payload":{"options":[{"id":"bc3cda00","text":"Ottawa"},{"id":"834cc36b","text":"Toronto"},{"id":"bef295a6","text":"Montréal"},{"id":"5248514a","text":"Vancouver"}]},"answer":{"option_id":"bc3cda00"}},{"external_key":"geo-003","concept_id":"geography.capitals.turkey","concept_label":"Capitale de la Turquie","type":"mcq","prompt":"Quelle est la capitale de la Turquie ?","explanation":"Mustafa Kemal Atatürk a fait d''Ankara la capitale en 1923. Istanbul reste la plus grande ville du pays.","difficulty":45,"status":"published","payload":{"options":[{"id":"dc967aae","text":"Ankara"},{"id":"177c4f0e","text":"Istanbul"},{"id":"71c14c55","text":"Izmir"},{"id":"ef96db6f","text":"Antalya"}]},"answer":{"option_id":"dc967aae"}},{"external_key":"geo-004","concept_id":"geography.capitals.brazil","concept_label":"Capitale du Brésil","type":"mcq","prompt":"Quelle est la capitale du Brésil ?","explanation":"Brasília, ville nouvelle inaugurée en 1960, a remplacé Rio de Janeiro. Ses plans sont signés Lúcio Costa et Oscar Niemeyer.","difficulty":45,"status":"published","payload":{"options":[{"id":"341f2631","text":"Brasília"},{"id":"9e26a4ed","text":"Rio de Janeiro"},{"id":"bbd3634e","text":"São Paulo"},{"id":"74b04d72","text":"Salvador"}]},"answer":{"option_id":"341f2631"}},{"external_key":"geo-005","concept_id":"geography.capitals.new_zealand","concept_label":"Capitale de la Nouvelle-Zélande","type":"mcq","prompt":"Quelle est la capitale de la Nouvelle-Zélande ?","explanation":"Wellington, au sud de l''île du Nord, est capitale depuis 1865. Auckland est plus peuplée.","difficulty":55,"status":"published","payload":{"options":[{"id":"3470534a","text":"Wellington"},{"id":"4460bd43","text":"Auckland"},{"id":"51f12ad8","text":"Christchurch"},{"id":"f40afccc","text":"Queenstown"}]},"answer":{"option_id":"3470534a"}},{"external_key":"geo-006","concept_id":"geography.capitals.morocco","concept_label":"Capitale du Maroc","type":"mcq","prompt":"Quelle est la capitale du Maroc ?","explanation":"Rabat est la capitale politique ; Casablanca est la plus grande ville et le poumon économique du pays.","difficulty":48,"status":"published","payload":{"options":[{"id":"6a9c9087","text":"Rabat"},{"id":"2a5dea63","text":"Casablanca"},{"id":"c2808cc2","text":"Marrakech"},{"id":"8a757b0d","text":"Fès"}]},"answer":{"option_id":"6a9c9087"}},{"external_key":"geo-007","concept_id":"geography.capitals.pairs_set1","concept_label":"Capitales : Norvège, Kenya, Pérou, Viêt Nam","type":"pairs","prompt":"Associe chaque pays à sa capitale.","explanation":"Oslo (Norvège), Nairobi (Kenya), Lima (Pérou), Hanoï (Viêt Nam). Hô Chi Minh-Ville, plus peuplée, n''est pas la capitale du Viêt Nam.","difficulty":45,"status":"published","payload":{"left":[{"id":"53e09ed9","text":"Norvège"},{"id":"6594977d","text":"Kenya"},{"id":"7f44c9a7","text":"Pérou"},{"id":"887d1f22","text":"Viêt Nam"}],"right":[{"id":"8396256f","text":"Oslo"},{"id":"9fd3f919","text":"Nairobi"},{"id":"74b83d36","text":"Lima"},{"id":"a333c832","text":"Hanoï"}]},"answer":{"pairs":{"53e09ed9":"8396256f","6594977d":"9fd3f919","7f44c9a7":"74b83d36","887d1f22":"a333c832"}}},{"external_key":"geo-008","concept_id":"geography.flags.japan","concept_label":"Drapeau du Japon","type":"mcq","prompt":"À quel pays appartient ce drapeau ? 🇯🇵","explanation":"Le Hinomaru, disque rouge sur fond blanc, représente le soleil. Le Bangladesh a un disque rouge sur fond vert.","difficulty":18,"status":"published","payload":{"options":[{"id":"ef722bee","text":"Japon"},{"id":"e3834bb3","text":"Corée du Sud"},{"id":"5b5be640","text":"Bangladesh"},{"id":"dd55cf6c","text":"Chine"}]},"answer":{"option_id":"ef722bee"}},{"external_key":"geo-009","concept_id":"geography.flags.ireland","concept_label":"Drapeau de l''Irlande","type":"mcq","prompt":"À quel pays appartient ce drapeau ? 🇮🇪","explanation":"Vert, blanc, orange depuis la hampe : c''est l''Irlande. La Côte d''Ivoire utilise les mêmes couleurs dans l''ordre inverse.","takeaway":"Irlande : le vert près du mât. Côte d''Ivoire : l''orange près du mât.","difficulty":55,"status":"published","payload":{"options":[{"id":"b5745f9d","text":"Irlande"},{"id":"7ed8620a","text":"Côte d''Ivoire"},{"id":"7ece7a00","text":"Italie"},{"id":"c389ac20","text":"Inde"}]},"answer":{"option_id":"b5745f9d"}},{"external_key":"geo-010","concept_id":"geography.flags.nepal","concept_label":"Drapeau du Népal","type":"mcq","prompt":"Quel pays a le seul drapeau national qui n''est pas rectangulaire ?","explanation":"Le drapeau du Népal est formé de deux triangles superposés. Ceux de la Suisse et du Vatican sont carrés, mais restent des quadrilatères.","difficu